class AutomatedTellerMachineSystem_AutoGenerated {
  /*SystemVariable Start*/
  PasswordValidated: boolean;
  WithdrawedNumber: number;
  InputCard: BankCard;
  CardIDValidated: boolean;
  IsDeposit: boolean;
  IsWithdraw: boolean;
  DepositedNumber: number;
  /*SystemVariable End*/

  /*the card id and password is validated and the input card exist, then if the money is withdraw,
   *if print the withdrawed number or if it is deposit print the deposited number or print 0*/
  printReceipt(): number {
    /*Definition Start*/
    let inputCardExists: boolean = l({
      logic: () => getRepository(BankCard).includes(this.InputCard),
      description: "BankCard.allInstance()->includes(InputCard)",
    }).build().pass;
    let cardStatusValid: boolean = l({
      logic: () => this.InputCard.CardStatus === BankCard.NORMAL,
      description: "InputCard.CardStatus=BankCard::NORMAL",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => this.CardIDValidated,
        description: "CardIDValidated",
      })
        .and({
          logic: () => this.PasswordValidated,
          description: "PasswordValidated",
        })
        .and({
          logic: () => inputCardExists,
          description: "inputCardExists",
        })
        .and({
          logic: () => cardStatusValid,
          description: "cardStatusValid",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let tempResult: number = l()
      .if({
        logic: () =>
          l({
            logic: () => StandardOPs.oclIsUndefined(this.InputCard),
            description: "InputCard.oclIsUndefined()",
          }),
        description: "InputCard.oclIsUndefined()",
        then: l({
          logic: () => 0,
          description: "0",
        }),
        else: l().if({
          logic: () =>
            l({
              logic: () => this.IsDeposit,
              description: "IsDeposit",
            }),
          description: "IsDeposit",
          then: l({
            execute: () => this.DepositedNumber,
            description: "DepositedNumber",
          }),
          else: l({
            execute: () => this.InputCard.Balance,
            description: "InputCard.Balance",
          }),
        }),
      })
      .build().pass;
    return l({
      execute: () => tempResult,
      description: "result=tempResult",
    }).build().value;
    /*Postcondition End*/
  }
}
export { AutomatedTellerMachineSystem_AutoGenerated };

